using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SandstormAction", menuName = "Data/Battle/Battle Actions/Sothis/Sandstorm Action")]
public class SandstormAction : BattleAction
{
	[Header("Soul Heat")]
	[SerializeField]
	private SoulHeat soulHeat;

	[SerializeField]
	private bool resetSoulHeat;

	[Header("Purified Lightning Action")]
	[SerializeField]
	private RandomEnemyLightningAction randomEnemyLightningAction;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	public int SoulHeatCounter => soulHeat.SoulHeatCounter;

	public bool ResetSoulHeat => resetSoulHeat;

	public PurifyAction PurifyAction => purifyAction;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return SoulHeatCounter > 0;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		GameObject vfx = null;
		ParticleEmissionController particleEmissionController = null;
		randomEnemyLightningAction.CastSothisSandstorm(SoulHeatCounter, amount, source, IsVFXEnabled() ? 0.2f : 0f, delegate
		{
			PlaySFXWithParameter("release", 0);
			if (IsVFXEnabled())
			{
				vfx = GetVFX();
				particleEmissionController = vfx.GetComponent<ParticleEmissionController>();
				particleEmissionController.SetActive(value: true);
			}
		}, delegate
		{
			SetSFXWithParameter("release", 1, release: true);
			if (IsVFXEnabled())
			{
				particleEmissionController.SetActive(value: false);
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vfx, 3f);
			}
			if (resetSoulHeat)
			{
				soulHeat.ResetSoulHeat();
			}
		});
	}
}
